private void permuteHelper(int[] nums, boolean[] visited, List<Integer> cur, List<List<Integer>> result) {
    if (cur.size() == nums.length) {
        result.add(new ArrayList<>(cur));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (visited[i]) {
            continue;
        }
        visited[i] = true;
        cur.add(nums[i]);
        permuteHelper(nums, visited, cur, result);
        cur.remove(cur.size() - 1);
        visited[i] = false;
    }
}

