public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]] = true;
    queue.add(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // Loop through all the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // If the path leads to an unvisited n-tersection, mark it as visited and add it to the queue
            if (paths[current][i] != -1 && !visited[paths[current][i]]) {
                visited[paths[current][i]] = true;
                queue.add(paths[current][i]);
            }
        }
    }

    // If the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Initialize a 2D array to represent the n-teresting space
    boolean[][] visited = new boolean[n][n];

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Use a queue to perform BFS
    Queue<Integer[]> queue = new LinkedList<>();
    queue.add(new Integer[] { start[0], start[1] });

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        Integer[] current = queue.remove();

        // Mark the current n-tersection as visited
        visited[current[0]][current[1]] = true;

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Add the unvisited neighboring n-tersections to the queue
        for (int i = 0; i < paths.length; i++) {
            int neighborRow = current[0] + paths[i][0];
            int neighborCol = current[1] + paths[i][1];
            if (neighborRow >= 0 && neighborRow < n && neighborCol >= 0 && neighborCol < n
                    && !visited[neighborRow][neighborCol]) {
                queue.add(new Integer[] { neighborRow, neighborCol });
            }
        }
    }

    // If we reach here, it means we were unable to find a path from the starting n-tersection to the ending n-tersection
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        if (i == start[0] && i == start[1]) {
            visited[i] = true;
        }
    }

    // Perform a depth-first search to determine if we can reach the end n-tersection
    if (dfs(n, start, end, paths, visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(int n, int[] start, int[] end, int[][] paths, boolean[] visited) {
    // If we have visited all n-tersections, return false
    if (Arrays.stream(visited).allMatch(b -> b)) {
        return false;
    }

    // If we have reached the end n-tersection, return true
    if (start[0] == end[0] && start[1] == end[1]) {
        return true;
    }

    // Try to visit the adjacent n-tersections
    for (int[] path : paths) {
        int currentX = start[0];
        int currentY = start[1];
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];

        // Make sure we are within the bounds of the n-teresting space
        if (nextX < 0 || nextX >= n || nextY < 0 || nextY >= n) {
            continue;
        }

        // If we have already visited this n-tersection, skip it
        if (visited[nextX + nextY * n]) {
            continue;
        }

        // Mark the current n-tersection as visited
        visited[currentX + currentY * n] = true;

        // Recursively search the adjacent n-tersections
        if (dfs(n, new int[] { nextX, nextY }, end, paths, visited)) {
            return true;
        }
    }

    // If we have not found a path to the end n-tersection, return false
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize the visited and queue arrays
    boolean[][] visited = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        Arrays.fill(visited[i], false);
    }
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);
    queue.add(start[1]);

    // Implement BFS to traverse the maze
    while (!queue.isEmpty()) {
        int currentX = queue.peek().intValue();
        int currentY = queue.peek().intValue();
        queue.poll();

        // If we have reached the end n-tersection, return "can be travelled"
        if (currentX == end[0] && currentY == end[1]) {
            return "can be travelled";
        }

        // Add all unvisited neighbors to the queue
        for (int i = 0; i < 4; i++) {
            int neighborX = currentX + i / 2;
            int neighborY = currentY + i % 2;
            if (neighborX >= 0 && neighborX < n && neighborY >= 0 && neighborY < n && !visited[neighborX][neighborY]) {
                queue.add(neighborX);
                queue.add(neighborY);
                visited[neighborX][neighborY] = true;
            }
        }
    }

    // If we have exhausted the queue and no path was found, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Define a 2D array to represent the maze
    boolean[][] maze = new boolean[n][n];

    // Set the start and end points in the maze
    maze[start[0]][start[1]] = true;
    maze[end[0]][end[1]] = true;

    // Iterate through the paths and set the corresponding cells in the maze
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
    }

    // Use DFS to traverse the maze and find the path from start to end
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (maze[i][j] && !maze[end[0]][end[1]]) {
                dfs(maze, i, j, end[0], end[1]);
            }
        }
    }

    // Check if the end point has been reached
    if (maze[end[0]][end[1]]) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static void dfs(boolean[][] maze, int i, int j, int endX, int endY) {
    if (maze[i][j]) {
        maze[i][j] = false;
        if (i == endX && j == endY) {
            return;
        }
        for (int[] neighbor : getNeighbors(i, j)) {
            dfs(maze, neighbor[0], neighbor[1], endX, endY);
        }
    }
}

private static ArrayList<int[]> getNeighbors(int x, int y) {
    ArrayList<int[]> neighbors = new ArrayList<>();
    if (x > 0) {
        neighbors.add(new int[]{x - 1, y});
    }
    if (x < maze.length - 1) {
        neighbors.add(new int[]{x + 1, y});
    }
    if (y > 0) {
        neighbors.add(new int[]{x, y - 1});
    }
    if (y < maze[0].length - 1) {
        neighbors.add(new int[]{x, y + 1});
    }
    return neighbors;
}

