public double trimMean(int[] arr) {
    int n = arr.length;
    int cutoff = (int) Math.ceil(n * 0.05);
    int[] sortedArr = Arrays.copyOf(arr, n);
    Arrays.sort(sortedArr);
    int start = cutoff;
    int end = n - cutoff;
    double sum = 0;
    for (int i = start; i < end; i++) {
        sum += sortedArr[i];
    }
    return sum / (n - 2 * cutoff + 1);
}

public double trimMean(int[] arr) {
  int n = arr.length;
  int left = (int)Math.ceil(n * 0.05);
  int right = (int)Math.ceil(n * 0.05);
  int[] leftArr = new int[left];
  int[] rightArr = new int[right];
  System.arraycopy(arr, 0, leftArr, 0, left);
  System.arraycopy(arr, n - right, rightArr, 0, right);
  Arrays.sort(leftArr);
  Arrays.sort(rightArr);
  int trimmedLength = n - left - right;
  int trimmedSum = 0;
  for (int i = left; i < trimmedLength; i++) {
    trimmedSum += arr[i];
  }
  return (double)trimmedSum / trimmedLength;
}

