        throw new IllegalArgumentException("Array must have at least 10 elements");
    }

    int n = arr.length;
    int trimsize = (int) (n * 0.05);

    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);

    int sum = 0;
    for (int i = trimsize; i < n - trimsize; i++) {
        sum += sorted[i];
    }

    return (double) sum / (n - 2 * trimsize);
}

