public static boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }

    int count = 0;
    int sum = 0;

    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }

    if (sum % k != 0) {
        return false;
    }

    int target = sum / k;

    for (int i = 0; i < arr.length; i++) {
        int tmp = target - arr[i];
        if (Arrays.binarySearch(arr, tmp) >= 0) {
            count++;
        }
    }

    return count >= arr.length / 2;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize the minimum time as 0
  int minTime = 0;

  // Iterate through the edges and nodes
  for (int i = 0; i < n; i++) {
    // If the current node has an apple, add the time required to collect it
    if (hasApple[i]) {
      minTime += findTime(i, edges);
    }
  }

  // Return the minimum time required to collect all the apples
  return minTime;
}

int findTime(int i, int[][] edges) {
  // Initialize the minimum time required to move from node i to node j as 0
  int minTime = 0;

  // Iterate through the edges incident to node i
  for (int j = 0; j < edges[i].length; j++) {
    // If the edge is incident to node j, add the time required to move from node i to node j
    if (edges[i][j] == 1) {
      minTime += 1;
    }
  }

  // Return the minimum time required to move from node i to node j
  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    // Iterate through all nodes and edges
    for (int i = 0; i < n; i++) {
        // Check if the current node has an apple
        if (hasApple[i]) {
            // Increment the minimum time required to collect the apple
            minTime++;

            // Iterate through all edges connected to the current node
            for (int j = 0; j < edges[i].length; j++) {
                // Check if the neighboring node has an apple
                if (hasApple[edges[i][j]]) {
                    // Increment the minimum time required to collect the apple
                    minTime++;
                }
            }
        }
    }

    return minTime;
}

