public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }
    char[] result = new char[s.length()];
    int currentPos = 0;
    while (currentPos < s.length()) {
        char currentChar = s.charAt(currentPos);
        int smallestIndex = currentPos;
        int largestIndex = currentPos;
        for (int i = currentPos + 1; i < s.length(); i++) {
            if (s.charAt(i) < currentChar) {
                smallestIndex = i;
            } else if (s.charAt(i) > currentChar) {
                largestIndex = i;
            }
        }
        result[currentPos] = currentChar;
        char temp = s.charAt(smallestIndex);
        s.setCharAt(smallestIndex, currentChar);
        s.setCharAt(currentPos, temp);
        currentPos++;
        result[currentPos] = s.charAt(largestIndex);
        temp = s.charAt(largestIndex);
        s.setCharAt(largestIndex, s.charAt(currentPos));
        s.setCharAt(currentPos, temp);
        currentPos++;
    }
    return new String(result);
}

