        chars.add(c);
    }
    while (chars.size() > 1) {
        char smallest = (char) 255;
        for (char c : chars) {
            if (c < smallest) {
                smallest = c;
            }
        }
        sorted.append(smallest);
        chars.remove(smallest);
        if (chars.size() > 1) {
            char largest = (char) 0;
            for (char c : chars) {
                if (c > largest) {
                    largest = c;
                }
            }
            sorted.append(largest);
            chars.remove(largest);
        }
    }
    if (chars.size() == 1) {
        sorted.append(chars.get(0));
    }
    return sorted.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    while (sb.length() < chars.length) {
        char smallest = chars[0];
        char largest = chars[chars.length - 1];
        sb.append(smallest).append(largest);
        chars = Arrays.copyOfRange(chars, 1, chars.length - 1);
        Arrays.sort(chars);
    }
    return sb.toString();
}

