public boolean hasAllCodes(String s, int k) {
  // check if the length of the string is greater than or equal to k
  if (s.length() < k) {
    return false;
  }

  // loop through each substring of length k and check if it is a binary string
  for (int i = 0; i <= s.length() - k; i++) {
    // get the substring of length k starting at index i
    String substr = s.substring(i, i + k);

    // check if the substring is a binary string
    if (!isBinary(substr)) {
      return false;
    }
  }

  // return true if all substrings of length k are binary strings
  return true;
}

