public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!allElementsEqual(arr)) {
        boolean hasModified = false;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (arr[i] > arr[j]) {
                    hasModified = true;
                    int tmp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = tmp;
                    minOperations++;
                    break;
                }
            }
            if (hasModified) {
                break;
            }
        }
    }
    return minOperations;
}

