public int minOperations(int n) {
    //initialize a variable to keep track of the minimum number of operations
    int minOperations = 0;

    // initialize an array with the given length
    int[] arr = new int[n];

    // loop through the array and perform the operations
    for (int i = 0; i < n; i++) {
        // compute the target value for the current element
        int target = (2 * i) + 1;

        // check if the current element is equal to the target value
        if (arr[i] != target) {
            // if not, find the index of the element that is closest to the target value
            int closestIndex = findClosestElement(arr, target);

            // perform the operation to make the current element equal to the target value
            arr[i] -= 1;
            arr[closestIndex] += 1;

            // increment the number of operations
            minOperations++;
        }
    }

    // return the minimum number of operations
    return minOperations;
}

private int findClosestElement(int[] arr, int target) {
    // initialize a variable to keep track of the minimum absolute difference
    int minAbsDiff = Integer.MAX_VALUE;
    int closestIndex = -1;

    // loop through the array and find the index of the element that is closest to the target value
    for (int i = 0; i < arr.length; i++) {
        int absDiff = Math.abs(arr[i] - target);
        if (absDiff < minAbsDiff) {
            minAbsDiff = absDiff;
            closestIndex = i;
        }
    }

    // return the index of the element that is closest to the target value
    return closestIndex;
}

