public int findMinFibonacciNumbers(int k) {
  int[] fibonacci = new int[]{1, 1};
  int count = 0;

  while (fibonacci[fibonacci.length - 1] < k) {
    int i = fibonacci[fibonacci.length - 1];
    fibonacci = Arrays.copyOf(fibonacci, fibonacci.length + 1);
    fibonacci[fibonacci.length - 1] = i + fibonacci[fibonacci.length - 2];
  }

  while (k > 0) {
    for (int i = fibonacci.length - 1; i >= 0; i--) {
      if (fibonacci[i] <= k) {
        k -= fibonacci[i];
        count++;
      }
    }
  }

  return count;
}

