public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int index = (k - 1) % 26;
        char c = (char) ('a' + index);
        sb.append(c);
        k -= index + 1;
    }
    return sb.toString();
}

public static String getSmallestString(int n, int k) {
    List<Character> alphabet = "abcdefghijklmnopqrstuvwxyz".chars().mapToObj(x -> (char) x).collect(Collectors.toList());
    Collections.sort(alphabet);
    String smallestString = "";
    while (smallestString.length() < n) {
        smallestString += alphabet.get(k % alphabet.size());
        k /= alphabet.size();
    }
    return smallestString;
}

