public static double calculateProbability(int n) {
    //calculate factorial of n
    double factorial = 1;
    for (int i = 1; i <= n; i++) {
        factorial *= i;
    }

    //calculate factorial of n-1
    double factorial_n_1 = 1;
    for (int i = 1; i < n; i++) {
        factorial_n_1 *= i;
    }

    //calculate probability
    double probability = (double)factorial / factorial_n_1;

    return probability;
}

