        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int left = j;
                int right = j;
                int up = i;
                int down = i;
                while (left >= 0 && mat[up][left] == 1) {
                    left--;
                }
                while (right < mat[up].length && mat[up][right] == 1) {
                    right++;
                }
                while (up >= 0 && mat[up][right] == 1) {
                    up--;
                }
                while (down < mat.length && mat[down][right] == 1) {
                    down++;
                }
                int length = right - left + 1;
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

