// Loop through each row and colum of the matrix
for (int i = 0; i < mat.length; i++) {
  for (int j = 0; j < mat[i].length; j++) {

    // If the current element is 1, increment the current line
    if (mat[i][j] == 1) {
      currentLine++;
    } else {

      // If the current element is 0, check if the current line is longer than the longest line
      if (currentLine > longestLine) {
        longestLine = currentLine;
      }

