public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;

                // Check horizontal line
                if (j > 0 && dp[i][j - 1] == 1) {
                    dp[i][j] = dp[i][j - 1] + 1;
                }

                // Check vertical line
                if (i > 0 && dp[i - 1][j] == 1) {
                    dp[i][j] = dp[i - 1][j] + 1;
                }

                // Check diagonal line
                if (i > 0 && j > 0 && dp[i - 1][j - 1] == 1) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                }

                // Check anti-diagonal line
                if (i > 0 && j < n - 1 && dp[i - 1][j + 1] == 1) {
                    dp[i][j] = dp[i - 1][j + 1] + 1;
                }

                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
