public static int findSmallestInteger(int n) {
    int smallestInteger = -1;
    int[] digits = new int[9];
    int i = 0;
    while (n > 0) {
        digits[i++] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits);
    for (int j = 0; j < i / 2; j++) {
        int tmp = digits[j];
        digits[j] = digits[i - j - 1];
        digits[i - j - 1] = tmp;
    }
    smallestInteger = Integer.parseInt(new String(digits));
    return smallestInteger;
}

public static int findSmallestInteger(int n) {
    int smallestInteger = -1;
    String digitString = String.valueOf(n);
    for (int i = 0; i < digitString.length(); i++) {
        String currentDigit = digitString.substring(i, i + 1);
        String remainingDigits = digitString.substring(0, i) + digitString.substring(i + 1);
        int currentDigitValue = Integer.parseInt(currentDigit);
        int rearrangeDigitValue = Integer.parseInt(remainingDigits);
        if (rearrangeDigitValue > currentDigitValue) {
            smallestInteger = rearrangeDigitValue;
            break;
        }
    }
    return smallestInteger;
}

public static int findSmallestInteger(int n) {
    int[] digits = getDigits(n);
    for (int i = 0; i < digits.length; i++) {
        int min = i + 1;
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[j] < digits[min]) {
                min = j;
            }
        }
        if (min != i) {
            int temp = digits[i];
            digits[i] = digits[min];
            digits[min] = temp;
        }
    }
    int result = 0;
    for (int i = 0; i < digits.length; i++) {
        result = result * 10 + digits[i];
    }
    return result;
}

private static int[] getDigits(int n) {
    String num = String.valueOf(n);
    int[] digits = new int[num.length()];
    for (int i = 0; i < num.length(); i++) {
        digits[i] = Character.getNumericValue(num.charAt(i));
    }
    return digits;
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    char[] digits = String.valueOf(n).toCharArray();
    Arrays.sort(digits);
    int min = 1;
    int max = Arrays.stream(digits).mapToInt(c -> c - '0').max().orElse(0);
    while (min <= max) {
        int mid = (min + max) / 2;
        if (canForm(digits, mid)) {
            smallest = mid;
            max = mid - 1;
        } else {
            min = mid + 1;
        }
    }
    return smallest;
}

private static boolean canForm(char[] digits, int n) {
    int[] count = new int[10];
    for (char c : digits) {
        count[c - '0']++;
    }
    for (int i = 0; i < 10; i++) {
        if (count[i] > 0) {
            n -= count[i];
            if (n < 0) {
                return false;
            }
        }
    }
    return true;
}

