public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    return (x1 - x2) * (y3 - y2) - (y1 - y2) * (x3 - x2) != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[][] edge1 = { points[1][0] - points[0][0], points[1][1] - points[0][1] };
    int[][] edge2 = { points[2][0] - points[1][0], points[2][1] - points[1][1] };
    int[][] edge3 = { points[0][0] - points[2][0], points[0][1] - points[2][1] };
    return edge1[0] * edge2[1] == edge1[1] * edge2[0] && edge2[0] * edge3[1] == edge2[1] * edge3[0];
}

