public static int findNthUglyNumber(int n) {
    // Initialize a list to store the ugly numbers
    List<Integer> uglyNumbers = new ArrayList<>();

    // Initialize variables to keep track of the current ugly number and its index
    int currentUglyNumber = 1;
    int currentIndex = 0;

    // Loop until the list has the desired number of ugly numbers
    while (uglyNumbers.size() < n) {
        // Check if the current number is ugly
        if (isUgly(currentUglyNumber)) {
            // If it is, add it to the list and increment the current index
            uglyNumbers.add(currentUglyNumber);
            currentIndex++;
        }

        // Increment the current number and its index
        currentUglyNumber++;
    }

    // Return the last ugly number in the list
    return uglyNumbers.get(uglyNumbers.size() - 1);
}

public static boolean isUgly(int num) {
    // Check if the number is divisible by 2, 3, or 5
    if (num % 2 == 0 || num % 3 == 0 || num % 5 == 0) {
        return true;
    }

    return false;
}

public static int findNthUglyNumber(int n) {
  // create a list to store the ugly numbers
  List<Integer> uglyNumbers = new ArrayList<>();

  // initialize two pointers for the 2, 3, and 5 factors
  int twoFactor = 2;
  int threeFactor = 3;
  int fiveFactor = 5;

  // loop until the nth ugly number is found
  for (int i = 1; i < n; i++) {
    // add the smallest possible value to the list
    uglyNumbers.add(Math.min(twoFactor, Math.min(threeFactor, fiveFactor)));

    // update the pointers
    if (uglyNumbers.get(i - 1) == twoFactor) {
      twoFactor *= 2;
    }
    if (uglyNumbers.get(i - 1) == threeFactor) {
      threeFactor *= 3;
    }
    if (uglyNumbers.get(i - 1) == fiveFactor) {
      fiveFactor *= 5;
    }
  }

  // return the nth ugly number
  return uglyNumbers.get(n - 1);
}

public static int findNthUglyNumber(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be greater than or equal to 1");
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i = 1;
    int j = 1;
    int k = 1;
    while (i < n) {
        int nextUglyNumber = Math.min(j, Math.min(k, i));
        if (nextUglyNumber == j) {
            j++;
        } else if (nextUglyNumber == k) {
            k++;
        } else {
            i++;
        }
        uglyNumbers[i] = nextUglyNumber;
    }
    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
        int[] dp = new int[n + 1];
        dp[1] = 1;
        int p2 = 1, p3 = 1, p5 = 1;
        int ugly = 1;
        for (int i = 2; i <= n; i++) {
            int m2 = dp[p2] * 2, m3 = dp[p3] * 3, m5 = dp[p5] * 5;
            ugly = Math.min(Math.min(m2, m3), m5);
            dp[i] = ugly;
            if (ugly == m2) {
                p2++;
            }
            if (ugly == m3) {
                p3++;
            }
            if (ugly == m5) {
                p5++;
            }
        }
        return dp[n];
    }

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }

    int[] uglyNumbers = { 1 };
    int index = 0;

    while (index < n) {
        int nextUglyNumber = getNextUglyNumber(uglyNumbers[index]);
        uglyNumbers[index++] = nextUglyNumber;
    }

    return uglyNumbers[n - 1];
}

private static int getNextUglyNumber(int number) {
    if (number % 2 == 0) {
        return number / 2;
    } else if (number % 3 == 0) {
        return number / 3;
    } else if (number % 5 == 0) {
        return number / 5;
    } else {
        return number;
    }
}

