public static int minPerfectSquareSum(int n) {
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int count = 0;
        int remaining = n - i * i;
        while (remaining > 0) {
            int squareRoot = (int) Math.sqrt(remaining);
            count++;
            remaining -= squareRoot * squareRoot;
        }
        minCount = Math.min(minCount, count);
    }
    return minCount;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        minSquares++;
        n -= root * root;
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int count = 0;
        int sum = 0;
        while (sum < n) {
            count++;
            sum += i * i;
        }
        minCount = Math.min(minCount, count);
    }
    return minCount;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sqrt = (int) Math.sqrt(n);
    while (sqrt > 0) {
        count++;
        n -= sqrt * sqrt;
        sqrt = (int) Math.sqrt(n);
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] wordChars = words[i].toCharArray();
        int j = 0;
        int k = wordChars.length - 1;
        while (j < k) {
            char temp = wordChars[j];
            wordChars[j] = wordChars[k];
            wordChars[k] = temp;
            j++;
            k--;
        }
        words[i] = String.valueOf(wordChars);
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        result.append(new StringBuffer(word).reverse().toString() + " ");
    }
    return result.toString().trim();
}

